"""CSV export of orders (no tests yet)."""

import csv
import io

COLUMNS = ["id", "customer_id", "status", "coupon", "lines", "charge_id"]


def _line_text(lines):
    parts = []
    for line in lines:
        parts.append("%s x%d @ %d" % (line["sku"], line["quantity"], line["unit_cents"]))
    return "; ".join(parts)


def _row(order):
    row = []
    for column in COLUMNS:
        if column == "lines":
            row.append(_line_text(order.get("lines", [])))
        else:
            row.append(order.get(column, ""))
    return row


def to_csv(orders, include_header=True):
    buffer = io.StringIO()
    writer = csv.writer(buffer)
    if include_header:
        writer.writerow(COLUMNS)
    for order_id in sorted(orders):
        writer.writerow(_row(orders[order_id]))
    return buffer.getvalue()


def by_status(orders, status):
    selected = {}
    for order_id, order in orders.items():
        if order.get("status") == status:
            selected[order_id] = order
    return selected


def by_customer(orders, customer_id):
    selected = {}
    for order_id, order in orders.items():
        if order.get("customer_id") == customer_id:
            selected[order_id] = order
    return selected


def write_file(orders, path):
    with open(path, "w", newline="") as fh:
        fh.write(to_csv(orders))
    return path


def group_by_sku(orders):
    totals = {}
    for order in orders.values():
        for line in order.get("lines", []):
            sku = line["sku"]
            if sku not in totals:
                totals[sku] = {"quantity": 0, "cents": 0}
            totals[sku]["quantity"] += line["quantity"]
            totals[sku]["cents"] += line["quantity"] * line["unit_cents"]
    return totals


def sku_report(orders):
    rows = []
    for sku, agg in sorted(group_by_sku(orders).items()):
        rows.append("%s,%d,%d" % (sku, agg["quantity"], agg["cents"]))
    if not rows:
        return "sku,quantity,cents\n"
    return "sku,quantity,cents\n" + "\n".join(rows) + "\n"


def customers(orders):
    seen = []
    for order in orders.values():
        customer = order.get("customer_id")
        if customer and customer not in seen:
            seen.append(customer)
    seen.sort()
    return seen


def status_counts(orders):
    counts = {}
    for order in orders.values():
        status = order.get("status", "draft")
        counts[status] = counts.get(status, 0) + 1
    return counts


def summary_line(orders):
    counts = status_counts(orders)
    parts = []
    for status in sorted(counts):
        parts.append("%s=%d" % (status, counts[status]))
    if not parts:
        return "no orders"
    return " ".join(parts)
